/* UNIVERSAL */
*{
    padding: 0;
    margin: 0;
} 
/* END OF UNIVERSAL */


/*********************************
     CERTIFICATE CONTAINER
/********************************/
.certificate-container {
    width: 100%;
    height: 100vh;
    padding: 40px;
    box-sizing: border-box;
    text-align: center;
    font-family: 'Georgia', serif;
    color: #222;
}

.border-pattern {
    /*border: 10px solid #D4AF37;*/
    border: 10px solid #09960e; /* GREENISH BORDER COLOR */
    padding: 20px;
    height: 100%;
    box-sizing: border-box;
    background: #FDFBF7;
}

h1 {
    font-size: 36px;
    color: #1a365d;
    margin-bottom: 10px;
}
.subtitle {
    font-size: 18px;
    font-style: italic;
    color: #555;
}

body{

    font-family:"Times New Roman", serif;
    background:white;
    color:#222;
    font-size:12pt;
    line-height:1.5;

}

/****************************************************
PAGE
****************************************************/

.page{

    position:relative;
    width:100%;
    /*min-height: auto;*/
    padding: 0px;
    /*backgmarging: 0;round:#fffdf7;*/
    /*border: 2px solid #7b6b30;*/
    box-sizing:border-box;
}

/****************************************************
INNER BORDER
****************************************************/

