/****************************************************
HEADER
****************************************************/

.logo{

    display:block;

    width: 100px;

    margin: 0 auto 6px;

}

.heading{

    text-align:center;

    color:#0c5f37;

}

.heading h1{

    font-size:22pt;

    margin:6px 0;

    font-weight:bold;

    letter-spacing:0.5px;

}

.heading h2{

    font-size:16pt;

    margin: 2px 0;

    font-weight:bold;

}

.heading h3{

    font-size:13pt;

    margin:6px 0;

    font-weight:bold;

}

.heading h4{

    font-size:12pt;

    margin:4px 0;

    font-weight:normal;

}

/****************************************************
TITLE
****************************************************/

.certificate-title{

    text-align:center;

    margin: 10px 0 15px;

    color:#0b5e3b;

    font-size: 24pt;
    
    letter-spacing:1px;
    
    font-family:"Times New Roman", serif;

}

/****************************************************
BODY
****************************************************/

.body{

    margin-top:10px;

    font-size:11pt;

    line-height:2;

}

.body p{
    margin-bottom:7px;
}

.cert-intro{
    text-align:center;
    font-size:12pt;
    margin-bottom:10px;
    font-style:italic;
}

.company-name{

    text-align:center;

    font-size:11pt;

    text-transform:uppercase;

    letter-spacing:1px;

    color:#0b5e3b;

    margin-bottom:6px;
    
    font-weight:bold;

}

.company-address{

    text-align:center;

    font-size:11pt;

    margin-bottom:15px;

}

.paragraph{

    text-align:justify;

    font-size:11pt;

    line-height:1;

}

.highlight{

    font-weight:bold;

    color:#0b5e3b;

    font-size:12pt;

}

/****************************************************
COMPANY
****************************************************/

.company{

    font-weight:bold;

    font-size:15pt;

    text-transform:uppercase;

}

/****************************************************
UNDERLINED VALUES
****************************************************/

.line{

    display:inline-block;

    border-bottom:1px dotted #0b5e3b;

    min-width:520px;

    padding-bottom:2px;

}

.line-small{

    /*display:inline-block;*/

    /*border-bottom:1px dotted #0b5e3b;*/

    /*min-width:180px;*/

    /*padding-bottom:2px;*/

}

.line-medium{

    display:inline-block;

    border-bottom:1px dotted #0b5e3b;

    min-width:280px;

    padding-bottom:2px;

}

/****************************************************
PARAGRAPH
****************************************************/

.paragraph{

    margin-top:25px;

    text-align:justify;

    font-style:italic;

    font-size:10pt;

    line-height:2;

}

/****************************************************
LEGAL TEXT
****************************************************/

.legal{

    text-align:center;

    font-size:10pt;

    color:#0c5f37;

    margin-top:1px 0;

    margin-bottom:8px;

    

}

/****************************************************
FOOTER
****************************************************/

.footer{

    margin-top:50px;

    width:100%;

}

.footer-table{

    width:100%;

    border-collapse:collapse;

}

.footer-table td{

    vertical-align:bottom;

}

/****************************************************
SEAL & CERTIFICATE NUMBER
****************************************************/

.footer-center{
    width:38%;
    text-align:center;
    vertical-align:top;
    
}

.seal{

    width:120px;
    margin-bottom:12px;

}

.certificate-meta{

    margin-top:8px;

}

.meta-label{

    font-size:6pt;

    text-transform:uppercase;

    font-weight:bold;

    color:#444;

    letter-spacing:.5px;

}

.meta-value{

    font-size:12pt;

    font-weight:bold;

    color:#0b5e3b;

    margin-top:2px;

}

/****************************************************
SIGNATURE
****************************************************/

.footer-right{

    width:34%;

    text-align:center;

}

.signature-space{

    width:180px;

    height:90px;

    margin:0 auto;

    border-bottom:1px solid #333;

}

.signature-name{

    margin-top:8px;

    font-size:13pt;

    font-weight:bold;

}

.signature-title{

    font-size:12pt;

    color:#0b5e3b;

}

/****************************************************
QR LEFT COLUMN
****************************************************/

.footer-left{

    width:25%;
    /*border:1px solid black;*/

}

/****************************************************
WATERMARK
****************************************************/

.watermark{
    position:absolute;
    top:45%;
    left:50%;
    transform:translate(-50%, -50%) rotate(-35deg);
    font-family:"Times New Roman", serif;
    font-size:22pt;
    font-weight:bold;
    letter-spacing:4px;
    text-transform:uppercase;
    color:#0b5e3b;
    opacity:0.1;
    white-space:nowrap;
    z-index:0;
    user-select:none;
}

/****************************************************
CONTENT
****************************************************/

.content{

    position:relative;

    z-index:2;

}

/****************************************************
PRINT
****************************************************/

table{

    width:100%;

    border-collapse:collapse;

}

td{

    vertical-align:top;

}

p{

    margin:0;

}

strong{

    font-weight:bold;

}
